const app=document.getElementById('app');
const KEY='boussoleFlowV7Complete';
const defaultState=()=>({screen:'home',q:0,answers:[],interestRatings:{},interestSubs:{},experiences:[],quals:[],skills:[],constraints:{physical:3,people:3,noise:3,shift:'maybe',training:2,mobility:'local'},result:null});
let st=defaultState();
try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&typeof x==='object')st={...defaultState(),...x,constraints:{...defaultState().constraints,...(x.constraints||{})}}}catch(e){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(st))}catch(e){}}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function brand(){return `<div class="top"><div class="brand">✦ BOUSSOLE FLOW</div><div class="tiny">V7 complète • contrôle</div></div>`}
function home(){st.screen='home';save();app.innerHTML=`<div class="wrap">${brand()}<section class="hero"><div><p class="eyebrow">Compatibilité professionnelle durable</p><h1>Comprendre qui tu es. Reconnaître ce que tu sais déjà faire. Trouver où tu peux durer.</h1><p class="lead">Un parcours complet : fonctionnement, centres d’intérêt gradués, expériences structurées, diplômes par domaine, compétences prouvées et contraintes réelles.</p><div class="pills"><span class="pill">🧠 40 questions</span><span class="pill">💜 40+ centres d’intérêt</span><span class="pill">🛠️ Parcours hiérarchique</span><span class="pill">🎓 Diplômes conditionnels</span></div><button class="btn primary" onclick="start()">Commencer mon exploration →</button>${st.answers.length?` <button class="btn" onclick="resume()">Reprendre</button>`:''}</div><div class="visual"><div class="head"></div><div class="orbit"></div><div class="node n1">Fonctionnement</div><div class="node n2">Passions</div><div class="node n3">Parcours</div><div class="node n4">Compétences</div></div></section><div class="features"><div class="card"><b>💜 Affinité</b><small>Ce qui t’attire profondément.</small></div><div class="card"><b>🧠 Fonctionnement</b><small>Le cadre dans lequel tu peux bien fonctionner.</small></div><div class="card"><b>🚀 Accessibilité</b><small>Ce que ton parcours rend réellement accessible.</small></div><div class="card"><b>🌱 Durabilité</b><small>Ce qui a des chances de tenir dans le temps.</small></div></div></div>`}
function start(){st=defaultState();st.screen='quiz';save();quiz()}
function resume(){if(st.result)return results();if(st.screen==='interests')return interestsScreen();if(st.screen==='experience')return manualExperienceScreen();if(st.screen==='quals')return qualsScreen();if(st.screen==='skills')return skillsScreen();if(st.screen==='constraints')return constraintsScreen();quiz()}
function quiz(){st.screen='quiz';save();const q=DATA.questions[st.q];app.innerHTML=`<div class="quiz">${brand()}<div class="qtop"><button class="round" onclick="qBack()">←</button><div class="progress"><i style="width:${Math.round(st.q/DATA.questions.length*100)}%"></i></div><span class="tiny">${st.q+1}/${DATA.questions.length}</span></div><div class="qbox"><p class="eyebrow">${q.cat}</p><h2>${q.text}</h2><div class="options">${q.choices.map((c,i)=>`<button class="opt" onclick="answer(${i})">${c.label}</button>`).join('')}</div></div></div>`}
function answer(i){st.answers[st.q]=i;if(st.q<DATA.questions.length-1){st.q++;save();quiz()}else{st.screen='interests';save();interestsScreen()}}
function qBack(){if(st.q>0){st.q--;quiz()}else home()}
function steps(active){const all=['Fonctionnement','Centres d’intérêt','Expériences','Diplômes','Compétences','Contraintes','Résultats'];return `<div class="stepbar">${all.map(x=>`<span class="stepchip ${x===active?'on':''}">${x}</span>`).join('')}</div>`}

function setRating(name,n){st.interestRatings[name]=n;if(n<3)st.interestSubs[name]=[];save();interestsScreen()}
function toggleSub(name,sub){const arr=st.interestSubs[name]||[];st.interestSubs[name]=arr.includes(sub)?arr.filter(x=>x!==sub):[...arr,sub];save();interestsScreen()}
function interestsScreen(){st.screen='interests';save();app.innerHTML=`<div class="wrap">${brand()}${steps('Centres d’intérêt')}<section class="section"><p class="eyebrow">Étape 2</p><h2>Qu’est-ce qui t’attire vraiment ?</h2><p class="sub">Attribue un degré de 0 à 4. Les intérêts notés 3 ou 4 s’ouvrent pour préciser tes sous-thèmes. Une passion influence l’affinité, jamais l’accessibilité.</p><div class="notice"><b>0</b> pas du tout • <b>1</b> j’aime bien • <b>2</b> j’aime beaucoup • <b>3</b> vraie passion • <b>4</b> je peux y passer des heures</div></section><div class="interestGrid section">${Object.entries(DATA.interests).map(([name,subs])=>{const r=st.interestRatings[name]||0;const sel=st.interestSubs[name]||[];return `<div class="interest"><div class="interestTop"><b>${name}</b><span class="tiny">niveau ${r}/4</span></div><div class="rating">${[0,1,2,3,4].map(n=>`<button class="rate ${r===n?'on':''}" onclick='setRating(${JSON.stringify(name)},${n})'>${n}</button>`).join('')}</div><div class="subthemes ${r>=3?'on':''}"><div class="tiny" style="margin-bottom:8px">Précise ce qui te passionne :</div><div class="chips">${subs.map(s=>`<button class="chip ${sel.includes(s)?'on':''}" onclick='toggleSub(${JSON.stringify(name)},${JSON.stringify(s)})'>${s}</button>`).join('')}</div></div></div>`}).join('')}</div><div class="actions"><button class="btn" onclick="st.q=DATA.questions.length-1;quiz()">← Retour</button><button class="btn primary" onclick="experienceEntryScreen()">Continuer →</button></div></div>`}

