function addExp(){const sec=Object.keys(DATA.taxonomy)[0],sub=Object.keys(DATA.taxonomy[sec])[0],role=DATA.taxonomy[sec][sub][0];st.experiences.push({sector:sec,sub,role,years:1,autonomy:3});save();manualExperienceScreen()}
