async function loadScriptOnce(src,id){
  if(document.getElementById(id)) return new Promise((resolve,reject)=>{
    const el=document.getElementById(id); if(el.dataset.ready==='1')resolve(); else {el.addEventListener('load',resolve,{once:true});el.addEventListener('error',reject,{once:true})}
  });
  return new Promise((resolve,reject)=>{
    const s=document.createElement('script');s.src=src;s.id=id;
    s.onload=()=>{s.dataset.ready='1';resolve()};s.onerror=reject;document.head.appendChild(s)
  })
}

async function extractPdfText(file){
  const mod=await import(window.BF_CDN.pdf);
  const data=new Uint8Array(await file.arrayBuffer());
  const pdf=await mod.getDocument({data}).promise;
  let txt='';
  for(let i=1;i<=pdf.numPages;i++){
    const page=await pdf.getPage(i), content=await page.getTextContent();
    txt += content.items.map(x=>x.str).join(' ')+'\n';
  }
  return txt;
}
async function extractDocxText(file){
  await loadScriptOnce(window.BF_CDN.mammoth,'bf-mammoth');
  const result=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});
  return result.value||'';
}
async function handleCvFile(file){
  if(!file)return;
  const status=document.getElementById('cvStatus');
  status.innerHTML=`<div class="analysisBox"><div class="spinner"></div><div><b>Lecture de ${esc(file.name)}…</b><p>Je repère les expériences, formations et compétences.</p></div></div>`;
  try{
    let raw='', name=file.name.toLowerCase();
    if(name.endsWith('.pdf')) raw=await extractPdfText(file);
    else if(name.endsWith('.docx')) raw=await extractDocxText(file);
    else raw=await file.text();
    if(!raw.trim())throw new Error("Le fichier ne contient pas de texte exploitable.");
    cvDetected=parseCvText(raw,file.name);
    cvReviewScreen();
  }catch(err){
    status.innerHTML=`<div class="importError"><b>Je n’ai pas réussi à lire ce fichier.</b><p>${esc(err.message||err)}</p><p>Essaie un autre PDF/DOCX, ou utilise la saisie manuelle.</p><button class="btn" onclick="manualExperienceScreen()">Saisir manuellement</button></div>`;
  }
}

function norm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,"'")}
function monthsToYears(s){
  const month={janvier:1,fevrier:2,mars:3,avril:4,mai:5,juin:6,juillet:7,aout:8,septembre:9,octobre:10,novembre:11,decembre:12,jan:1,fev:2,avr:4,juil:7,sep:9,sept:9,oct:10,nov:11,dec:12};
  const n=norm(s);
  let m=n.match(/(?:(janvier|fevrier|mars|avril|mai|juin|juillet|aout|septembre|octobre|novembre|decembre|jan|fev|avr|juil|sep|sept|oct|nov|dec)\s+)?(19\d{2}|20\d{2})\s*(?:-|–|—|a|au)\s*(?:(janvier|fevrier|mars|avril|mai|juin|juillet|aout|septembre|octobre|novembre|decembre|jan|fev|avr|juil|sep|sept|oct|nov|dec)\s+)?(19\d{2}|20\d{2}|aujourd'hui|present)/);
  if(!m)return null;
  const y1=+m[2], mo1=month[m[1]]||6;
  let y2,mo2;
  if(/aujourd|present/.test(m[4])){const d=new Date();y2=d.getFullYear();mo2=d.getMonth()+1}else{y2=+m[4];mo2=month[m[3]]||6}
  const yrs=Math.max(.25,((y2-y1)*12+(mo2-mo1))/12);
  return Math.round(yrs*2)/2;
}
