function applyCvDetection(){
  if(cvDetected.experiences.length)st.experiences=cvDetected.experiences.map(({detectedFrom,confidence,...e})=>e);
  if(cvDetected.quals.length)st.quals=cvDetected.quals;
  if(cvDetected.skills.length)st.skills=cvDetected.skills.map(({detected,...s})=>s);
  save();manualExperienceScreen()
}

